/**
 * Golden contract for the SM-18 format-read port follow-up on
 * `info/RepetitionHistory.dat` (sm18-re gitlab #41).
 *
 * Follow-up to #36. The fixture
 * `test/fixtures/sm18-port-format-read-rephistory.json` is a mirror of
 * `sm18-re:tests/fixtures/port-format-read-rephistory.json`, regenerated by
 * `sm18-re:scripts/export-port-format-read-rephistory-fixture.py`. ABC's
 * `RepetitionHistory.dat` is zero bytes so the fixture also pins Net+ and
 * SANS; Cyber is excluded on size (see `excluded_oversize`).
 *
 * This file is brief-writer owned. The lane adds
 *
 *   parseRepetitionHistory(bytes: Uint8Array): RepetitionHistoryRecord[]
 *
 * to `src/sm18-format-read.ts` additively.
 *
 * Record geometry (do NOT treat as a contiguous struct; the Python reference
 * reads each field at its own offset and so must the port):
 *
 *   record size:     0x27 (39 bytes)
 *   header:          none
 *   element_id       u32   offset 0x00
 *   repetition_number u16  offset 0x04
 *   lapse_count      u16   offset 0x06
 *   interval_days    u16   offset 0x08
 *   repetition_date  f64   offset 0x0a   <-- deliberately unaligned
 *   grade            i8    offset 0x18   <-- signed byte, sign-extend
 *
 * `repetition_date` stays a raw IEEE-754 double. TDateTime counts days since
 * 1899-12-30; the port does NOT convert to a JS `Date` on this lane. A
 * conversion is a semantic layer, it loses the exact bytes, and the fixture
 * pins the number.
 *
 * `grade` is the only signed member in the record. ABC never exercises a
 * negative value and Net+/SANS never see one either, so the signed-decode is
 * proven off-fixture with a synthetic buffer whose grade byte is 0x80 (-128)
 * — a port that reads it as unsigned would return 128.
 *
 * Error contract: a file whose length is not a multiple of 39 must throw.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-read-rephistory.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-read.ts"].join("/");

interface RepetitionHistoryRecord {
  element_id: number;
  repetition_number: number;
  lapse_count: number;
  interval_days: number;
  repetition_date: number;
  grade: number;
}

interface FixtureFile {
  collection: string;
  path: string;
  byte_length: number;
  bytes_b64: string;
  record_count: number;
  records: RepetitionHistoryRecord[];
}

interface Fixture {
  schema: number;
  scope: string[];
  max_records_per_file: number;
  excluded_oversize: string[];
  files: FixtureFile[];
}

interface PortModule {
  parseRepetitionHistory: (bytes: Uint8Array) => RepetitionHistoryRecord[];
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (typeof mod?.parseRepetitionHistory !== "function") {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the rephistory scope and well-formed files", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["repetition_history"]);
  assert.ok(fixture.files.length > 0);
  for (const file of fixture.files) {
    assert.equal(
      file.byte_length % 0x27,
      0,
      `${file.path} byte length must be a multiple of 39`,
    );
    assert.equal(file.record_count * 0x27, file.byte_length);
    assert.equal(file.records.length, file.record_count);
  }
});

test("src/sm18-format-read.ts exports parseRepetitionHistory", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseRepetitionHistory not implemented yet");
    return;
  }
  assert.equal(typeof port.parseRepetitionHistory, "function");
});

test("parseRepetitionHistory throws on a byte length not a multiple of 39", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseRepetitionHistory not implemented yet");
    return;
  }
  const partial = new Uint8Array(0x27 + 1);
  assert.throws(() => port.parseRepetitionHistory(partial));
});

test("parseRepetitionHistory sign-extends grade (synthetic -128 case)", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseRepetitionHistory not implemented yet");
    return;
  }
  // Build one record: element_id=1, every u16 field = 0, repetition_date = 0.0,
  // grade = 0x80 (-128 if sign-extended, 128 if read as u8).
  const buf = new Uint8Array(0x27);
  buf[0] = 1;
  // bytes 0x0a..0x11 (8 bytes of double) left as zero -> 0.0
  buf[0x18] = 0x80;
  const parsed = port.parseRepetitionHistory(buf);
  assert.equal(parsed.length, 1);
  assert.equal(parsed[0].grade, -128, "grade must sign-extend from int8");
  assert.equal(parsed[0].element_id, 1);
});

for (const file of fixture.files) {
  test(`format-read-rephistory: ${file.path} parses to ${file.record_count} records`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("parseRepetitionHistory not implemented yet");
      return;
    }
    const bytes = decodeBase64(file.bytes_b64);
    assert.equal(
      bytes.byteLength,
      file.byte_length,
      `byte count for ${file.path}`,
    );
    const parsed = port.parseRepetitionHistory(bytes);
    assert.equal(
      parsed.length,
      file.record_count,
      `record count for ${file.path}`,
    );
    for (let i = 0; i < file.record_count; i += 1) {
      assert.deepEqual(
        parsed[i],
        file.records[i],
        `record ${i} of ${file.path} must match the fixture projection`,
      );
    }
  });
}
